  bool operator ==(Object other) =>
      identical(this, other) ||
      other is ModelView &&
          runtimeType == other.runtimeType &&
          id == other.id &&
          status == other.status &&
          replicas == other.replicas &&
          tokensPerSec == other.tokensPerSec &&
          context == other.context &&
          nodes == other.nodes &&
          standin == other.standin;
}

/// [`PairState`] flattened: `state` is `unpaired`, `offering`, `confirm`, `waiting`, `linked`
/// or `failed`; the other fields are set when that state has them.
class PairView {
  final String state;
  final String? link;
  final PlatformInt64? expiresMs;
  final String? sas;
  final String? user;
  final String? device;
  final String? message;

  const PairView({
    required this.state,
    this.link,
    this.expiresMs,
    this.sas,
    this.user,
    this.device,
    this.message,
  });

  static Future<PairView> default_() =>
      RustLib.instance.api.crateApiBragiPairViewDefault();

  @override
  int get hashCode =>
      state.hashCode ^
      link.hashCode ^
      expiresMs.hashCode ^
      sas.hashCode ^
      user.hashCode ^
      device.hashCode ^
      message.hashCode;

  @override
  bool operator ==(Object other) =>
      identical(this, other) ||
      other is PairView &&
          runtimeType == other.runtimeType &&
          state == other.state &&
          link == other.link &&
          expiresMs == other.expiresMs &&
          sas == other.sas &&
          user == other.user &&
          device == other.device &&
          message == other.message;
}

/// `kind` is `weirdnet`, `fallback`, `endpoint` or `none`; `detail` is one line for the UI.
class RouteView {
  final String kind;
  final String? endpoint;
  final String detail;

  const RouteView({required this.kind, this.endpoint, required this.detail});

  @override
  int get hashCode => kind.hashCode ^ endpoint.hashCode ^ detail.hashCode;

  @override
  bool operator ==(Object other) =>
      identical(this, other) ||
      other is RouteView &&
          runtimeType == other.runtimeType &&
          kind == other.kind &&
          endpoint == other.endpoint &&
          detail == other.detail;
}

/// A session: `endpoint_id` is set when it sends to an endpoint, else it sends to Weirdnet.
class SessionView {
  final String id;
  final String name;
  final String? endpointId;

  /// What it sends to, for the UI: `Weirdnet` or the endpoint's name.
  final String targetName;
  final String? model;
  final String? folder;

  const SessionView({
    required this.id,
    required this.name,
    this.endpointId,
    required this.targetName,
    this.model,
    this.folder,
  });

  @override
  int get hashCode =>
      id.hashCode ^
      name.hashCode ^
      endpointId.hashCode ^
      targetName.hashCode ^
      model.hashCode ^
      folder.hashCode;

  @override
  bool operator ==(Object other) =>
      identical(this, other) ||
      other is SessionView &&
          runtimeType == other.runtimeType &&
          id == other.id &&
          name == other.name &&
          endpointId == other.endpointId &&
          targetName == other.targetName &&
          model == other.model &&
          folder == other.folder;
}

class StateView {
  final PairView pair;
  final bool online;

  /// Inference nodes found among the user's devices.
  final int nodeCount;

  /// The open session's models (the pool's, the fallback's while no node answers, or its endpoint's).
  final List<ModelView> models;
  final String? defaultModel;

  /// Where the open session's next message goes.
  final RouteView route;
  final List<EndpointView> endpoints;
  final List<SessionView> sessions;
  final List<FolderView> folders;
  final String activeSession;

  /// The session tree as drawn, depth first (a collapsed folder's insides left out).
  final List<TreeRowView> tree;

  /// The Weirdnet node addresses this device dials.
  final List<LinkView> links;

  const StateView({
    required this.pair,
    required this.online,
    required this.nodeCount,
    required this.models,
    this.defaultModel,
    required this.route,
    required this.endpoints,
    required this.sessions,
    required this.folders,
    required this.activeSession,
    required this.tree,
    required this.links,
  });

  @override
  int get hashCode =>
      pair.hashCode ^
      online.hashCode ^
      nodeCount.hashCode ^
      models.hashCode ^
      defaultModel.hashCode ^
      route.hashCode ^
      endpoints.hashCode ^
      sessions.hashCode ^
      folders.hashCode ^
      activeSession.hashCode ^
      tree.hashCode ^
      links.hashCode;

  @override
  bool operator ==(Object other) =>
      identical(this, other) ||
      other is StateView &&
          runtimeType == other.runtimeType &&
          pair == other.pair &&
          online == other.online &&
          nodeCount == other.nodeCount &&
          models == other.models &&
          defaultModel == other.defaultModel &&
          route == other.route &&
          endpoints == other.endpoints &&
          sessions == other.sessions &&
          folders == other.folders &&
          activeSession == other.activeSession &&
          tree == other.tree &&
          links == other.links;
}

